{
  "name": "bitfolk",
  "version": "0.1.12",
  "description": "Link this computer to your Bitfolk team so it can start Claude Code, Codex, OpenCode and other coding sessions here, from any device.",
  "keywords": [
    "bitfolk",
    "cli",
    "claude-code",
    "codex",
    "opencode",
    "coding-agent",
    "ai-agents",
    "runner"
  ],
  "homepage": "https://bitfolk.ai",
  "license": "SEE LICENSE IN LICENSE",
  "bugs": {
    "url": "https://bitfolk.ai/bug"
  },
  "type": "module",
  "bin": {
    "bitfolk": "dist/bin.js",
    "bf": "dist/bin.js"
  },
  "files": [
    "dist",
    "LICENSE"
  ],
  "engines": {
    "node": ">=20"
  },
  "os": [
    "darwin",
    "linux"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "tsc --noEmit -p tsconfig.build.json && node scripts/build.mjs",
    "prepack": "npm run build",
    "dev": "node src/main.ts",
    "typecheck": "tsc --noEmit",
    "lint": "tsc --noEmit",
    "test": "vitest run"
  },
  "devDependencies": {
    "@types/node": "22.20.5",
    "rolldown": "1.2.16",
    "typescript": "5.9.3",
    "vitest": "5.1.0"
  },
  "dependencies": {
    "@ngrok/ngrok": "1.7.0"
  }
}
